      el: { title: "Ορός-Κρέμα Ματιών Awaken", shortDescription: "Δροσιστική κρέμα ματιών με καφεΐνη και πεπτίδια σε σωλήνα roller.", description: "Ένας υβριδικός ορός-κρέμα για την ευαίσθητη περιοχή των ματιών, που συνδυάζει καφεΐνη, ένα θρεπτικό σύμπλεγμα πεπτιδίων και δροσιστικό εκχύλισμα αγγουριού. Απλώνεται με έναν αναζωογονητικό roller εφαρμογέα για ένα ορατά πιο λαμπερό, ξεκούραστο βλέμμα." },
      pl: { title: "Serum-Krem pod Oczy Awaken", shortDescription: "Chłodzący krem pod oczy z kofeiną i peptydami w wygodnym rollerze.", description: "Hybrydowe serum-krem do delikatnej skóry wokół oczu, łączące kofeinę, odżywczy kompleks peptydowy i chłodzący ekstrakt z ogórka. Aplikowany za pomocą odświeżającego rollera, zapewnia widocznie jaśniejsze, bardziej wypoczęte spojrzenie." },
      ro: { title: "Ser-Cremă pentru Ochi Awaken", shortDescription: "Cremă răcoritoare pentru ochi cu cafeină și peptide, în tub cu roller.", description: "Un ser-cremă hibrid pentru zona delicată a ochilor, care combină cafeina, un complex hrănitor de peptide și extract răcoritor de castravete. Se aplică cu un aplicator roller răcoritor pentru o privire vizibil mai luminoasă și mai odihnită." },
      cs: { title: "Sérum-Krém na Oči Awaken", shortDescription: "Chladivý oční krém s kofeinem a peptidy v praktické roller tubě.", description: "Hybridní sérum-krém pro citlivou oblast očí, kombinující kofein, vyživující peptidový komplex a chladivý výtažek z okurky. Nanáší se osvěžujícím roller aplikátorem pro viditelně jasnější, probuzenější pohled." },
      hu: { title: "Awaken Szemkörnyékápoló Szérum-Krém", shortDescription: "Hűsítő szemkrém koffeinnel és peptidekkel, kényelmes roller tubusban.", description: "Hibrid szérum-krém az érzékeny szemkörnyékre, koffeint, tápláló peptidkomplexet és hűsítő uborkakivonatot ötvözve. Frissítő roller applikátorral vihető fel a láthatóan ragyogóbb, ébredtebb tekintetért." },
      uk: { title: "Сироватка-Крем для Очей Awaken", shortDescription: "Охолоджувальний крем для очей із кофеїном і пептидами в зручному роликовому тюбику.", description: "Гібридна сироватка-крем для делікатної зони навколо очей, що поєднує кофеїн, живильний пептидний комплекс і охолоджувальний екстракт огірка. Наноситься освіжаючим роликовим аплікатором для видимо світлішого, більш бадьорого погляду." },
      ru: { title: "Сыворотка-Крем для Глаз Awaken", shortDescription: "Охлаждающий крем для глаз с кофеином и пептидами в удобном тюбике-роллере.", description: "Гибридная сыворотка-крем для деликатной области вокруг глаз, сочетающая кофеин, питательный пептидный комплекс и охлаждающий экстракт огурца. Наносится освежающим роликовым аппликатором для видимо более сияющего, отдохнувшего взгляда." },
