      ro: { title: "Mască Purificatoare cu Argilă", shortDescription: "Mască detoxifiantă cu argilă caolin și bentonită cu ulei de arbore de ceai.", description: "O mască săptămânală matifiantă ce combină argilele caolin și bentonită cu ulei clarifiant din frunze de arbore de ceai. Extrage impuritățile și luciul excesiv, lăsând pielea cu aspect rafinat, echilibrat și revigorat." },
      cs: { title: "Čisticí Jílová Maska", shortDescription: "Detoxikační jílová maska s kaolinem a bentonitem s olejem z čajovníku.", description: "Matující týdenní pleťová maska kombinující kaolinový a bentonitový jíl s čisticím olejem z listů čajovníku. Odstraňuje nečistoty a přebytečný lesk, díky čemuž pleť vypadá zjemněná, vyrovnaná a osvěžená." },
      hu: { title: "Purifying Tisztító Agyagpakolás", shortDescription: "Méregtelenítő kaolin- és bentonitagyag-maszk teafaolajjal.", description: "Mattító heti kezelőmaszk, amely kaolin- és bentonitagyagot ötvöz tisztító teafalevél-olajjal. Kivonja a szennyeződéseket és a felesleges fényt, finomabb, kiegyensúlyozottabb, felfrissült bőrt hagyva maga után." },
      uk: { title: "Очищувальна Глиняна Маска", shortDescription: "Детокс-маска з каоліну та бентоніту з олією чайного дерева.", description: "Матувальна щотижнева маска, що поєднує каолінову та бентонітову глину з очищувальною олією листя чайного дерева. Витягує забруднення та зайвий блиск, залишаючи шкіру вишуканою, збалансованою та освіженою." },
      ru: { title: "Очищающая Глиняная Маска", shortDescription: "Детокс-маска с каолином и бентонитом с маслом чайного дерева.", description: "Матирующая еженедельная маска, сочетающая каолиновую и бентонитовую глину с очищающим маслом листьев чайного дерева. Вытягивает загрязнения и лишний блеск, оставляя кожу утончённой, сбалансированной и посвежевшей." },
      bg: { title: "Пречистваща Глинена Маска", shortDescription: "Детоксикираща маска с каолинова и бентонитова глина с масло от чаено дърво.", description: "Матираща седмична маска, съчетаваща каолинова и бентонитова глина с прочистващо масло от листа на чаено дърво. Извлича замърсяванията и излишния блясък, оставяйки кожата изтънчена, балансирана и освежена." },
      sk: { title: "Čistiaca Ílová Maska", shortDescription: "Detoxikačná ílová maska s kaolínom a bentonitom s olejom z čajovníka.", description: "Matujúca týždenná pleťová maska kombinujúca kaolínový a bentonitový íl s čistiacim olejom z listov čajovníka. Odstraňuje nečistoty a prebytočný lesk a zanecháva pleť zjemnenú, vyváženú a osviežená." },
      lt: { title: "Purifying Valomoji Molio Kaukė", shortDescription: "Detoksikuojanti kaolino ir bentonito molio kaukė su arbatmedžio aliejumi.", description: "Matinanti savaitinė kaukė, jungianti kaolino ir bentonito molį su valomuoju arbatmedžio lapų aliejumi. Ištraukia nešvarumus ir perteklinį blizgesį, palikdama odą subtilesnę, subalansuotą ir atgaivintą." },
      ar: { title: "قناع الطين المنقي", shortDescription: "قناع مزيل للسموم من طين الكاولين والبنتونيت بزيت شجرة الشاي.", description: "قناع أسبوعي مطفٍ يمزج بين طيني الكاولين والبنتونيت مع زيت أوراق شجرة الشاي المنقي. يسحب الشوائب واللمعان الزائد، تاركاً البشرة تبدو منقحة ومتوازنة ومنتعشة." },
      tr: { title: "Purifying Arındırıcı Kil Maskesi", shortDescription: "Çay ağacı yağlı, detoks etkili kaolin ve bentonit kil maskesi.", description: "Kaolin ve bentonit killerini arındırıcı çay ağacı yaprağı yağıyla birleştiren, matlaştırıcı haftalık bakım maskesi. Kirlilikleri ve fazla parlaklığı çeker, cildi arınmış, dengeli ve tazelenmiş bırakır." },
      "zh-CN": { title: "净透泥膜", shortDescription: "高岭土与膨润土排毒净化面膜,添加茶树精油。", description: "这款控油哑光每周护理面膜融合高岭土与膨润土两种矿物泥,搭配澄净茶树叶精油。深层吸附杂质与多余油光,令肌肤看起来更细腻、更平衡、更清爽。" },
      "zh-TW": { title: "淨透泥膜", shortDescription: "高嶺土與膨潤土排毒淨化面膜,添加茶樹精油。", description: "這款控油霧面每週護理面膜融合高嶺土與膨潤土兩種礦物泥,搭配澄淨茶樹葉精油。深層吸附雜質與多餘油光,令肌膚看起來更細緻、更平衡、更清爽。" },
      ja: { title: "ピュリファイング クレイマスク", shortDescription: "カオリンとベントナイトのデトックスクレイマスク、ティーツリーオイル配合。", description: "カオリンとベントナイトのクレイに、清浄作用のあるティーツリーリーフオイルをブレンドした、皮脂を整える週1回のスペシャルケアマスク。汚れや余分なテカリを吸着し、肌をきめ細かく、バランスの取れた、リフレッシュした印象へ導きます。" },
      ko: { title: "퓨리파잉 클레이 마스크", shortDescription: "티트리 오일을 담은 카올린 & 벤토나이트 디톡스 클레이 마스크.", description: "카올린과 벤토나이트 클레이에 정화력 있는 티트리 잎 오일을 더한 매트한 마무리감의 주간 케어 마스크입니다. 노폐물과 과도한 유분을 흡착하여 피부를 한층 정돈되고 균형 잡히고 산뜻하게 가꿔줍니다." },
