      nl: { title: "Rozenwater Balancing Toner", shortDescription: "Biologische rozenwatertoner met glycerine in fijne mistspray.", description: "Een zachte, biologische toner gemaakt met pure Rosa Damascena rozenwater en hydraterende glycerine. Verspreid in een fijne nevel, brengt het de huid in balans en verfrist het, waardoor deze klaargemaakt wordt om volgende producten beter op te nemen." },
      sv: { title: "Rosenvatten Balancing Toner", shortDescription: "Ekologisk rosenvattentoner med glycerin i fin dimspray.", description: "En skonsam, ekologisk toner gjord med rent Rosa Damascena-rosenvatten och fuktgivande glycerin. Sprayas som en fin dimma, balanserar och fräschar upp huden och förbereder den för att bättre absorbera efterföljande produkter." },
      el: { title: "Τονωτικό Ισορροπίας Ροδόνερου", shortDescription: "Βιολογικό τονωτικό ροδόνερου με γλυκερίνη σε ψιλό σπρέι.", description: "Ένα ήπιο, βιολογικό τονωτικό φτιαγμένο με καθαρό ροδόνερο Rosa Damascena και ενυδατική γλυκερίνη. Διανέμεται σε ψιλό σπρέι, ισορροπεί και αναζωογονεί την επιδερμίδα, προετοιμάζοντάς την να απορροφήσει καλύτερα τα επόμενα προϊόντα." },
      pl: { title: "Tonik Różany Przywracający Równowagę", shortDescription: "Organiczny tonik z wody różanej z gliceryną w delikatnej mgiełce.", description: "Delikatny, organiczny tonik wykonany z czystej wody z róży damasceńskiej i nawilżającej gliceryny. Podawany w postaci delikatnej mgiełki, równoważy i odświeża skórę, przygotowując ją do lepszego wchłaniania kolejnych produktów." },
      ro: { title: "Tonic de Echilibrare cu Apă de Trandafiri", shortDescription: "Tonic organic cu apă de trandafiri și glicerină, în spray cu ceață fină.", description: "Un tonic organic și delicat, realizat cu apă pură de trandafir Damascena și glicerină hidratantă. Livrat printr-o ceață fină, echilibrează și revigorează pielea, pregătind-o să absoarbă mai bine produsele următoare." },
      cs: { title: "Vyvažující Tonikum s Růžovou Vodou", shortDescription: "Organické tonikum s růžovou vodou a glycerinem v jemné mlžné spreji.", description: "Jemné, organické tonikum vyrobené z čisté růžové vody Rosa Damascena a hydratačního glycerinu. Aplikuje se jako jemná mlha, vyvažuje a osvěžuje pleť a připravuje ji na lepší vstřebávání následujících produktů." },
      hu: { title: "Rosewater Balancing Tonik", shortDescription: "Bio rózsavizes tonik glicerinnel, finom permetes spray-ben.", description: "Kímélő, bio tonik, mely tiszta Rosa Damascena rózsavizet és hidratáló glicerint tartalmaz. Finom permet formájában juttatható a bőrre, kiegyensúlyozza és felfrissíti azt, felkészítve a következő termékek jobb felszívódására." },
