      ru: { title: "Балансирующий Тоник с Розовой Водой", shortDescription: "Органический тоник с розовой водой и глицерином в мелкодисперсном спрее.", description: "Мягкий, органический тоник, приготовленный из чистой розовой воды Rosa Damascena и увлажняющего глицерина. Распыляется мелким туманом, балансирует и освежает кожу, подготавливая её к лучшему усвоению последующих средств." },
      bg: { title: "Балансиращ Тоник с Розова Вода", shortDescription: "Органичен тоник с розова вода и глицерин в фин спрей мъгла.", description: "Мек, органичен тоник, приготвен от чиста розова вода Rosa Damascena и хидратиращ глицерин. Разпръсква се като фина мъгла, балансира и освежава кожата, подготвяйки я за по-добро усвояване на следващите продукти." },
      sk: { title: "Vyvažujúce Tonikum s Ružovou Vodou", shortDescription: "Organické tonikum s ružovou vodou a glycerínom v jemnom hmlovom spreji.", description: "Jemné, organické tonikum vyrobené z čistej ružovej vody Rosa Damascena a hydratačného glycerínu. Aplikuje sa ako jemná hmla, vyvažuje a osviežuje pleť a pripravuje ju na lepšie vstrebávanie nasledujúcich produktov." },
      lt: { title: "Rosewater Balansuojantis Tonikas", shortDescription: "Organinis rožių vandens tonikas su glicerinu smulkaus purškimo buteliuke.", description: "Švelnus, organinis tonikas, pagamintas iš gryno Rosa Damascena rožių vandens ir drėkinančio glicerino. Purškiamas smulkiu debesėliu, jis balansuoja ir gaivina odą, paruošdamas ją geriau įsisavinti kitus produktus." },
      ar: { title: "تونر ماء الورد المتوازن", shortDescription: "تونر عضوي بماء زهر الورد والجلسرين برذاذ ناعم.", description: "تونر عضوي لطيف مصنوع من ماء زهر الورد الدمشقي النقي والجلسرين المرطب. يُوزَّع برذاذ ناعم، فيوازن البشرة وينعشها، ويهيئها لامتصاص أفضل للمنتجات التالية." },
      tr: { title: "Rosewater Dengeleyici Tonik", shortDescription: "İnce sisli spreyde gliserinli organik gül suyu toniği.", description: "Saf Rosa Damascena gül suyu ve nemlendirici gliserinle hazırlanmış, hassas ve organik bir tonik. İnce bir sis şeklinde uygulanarak cildi dengeler ve tazeler, ardından gelen ürünleri daha iyi emmesi için hazırlar." },
      "zh-CN": { title: "玫瑰水平衡爽肤水", shortDescription: "有机玫瑰花水与甘油调配,细腻喷雾质地。", description: "这款温和的有机爽肤水选用纯正大马士革玫瑰花水与保湿甘油精心调配。以细腻喷雾形式呈现,平衡并舒缓肌肤,为后续护肤品的吸收做好准备。" },
      "zh-TW": { title: "玫瑰水平衡化妝水", shortDescription: "有機玫瑰花水與甘油調配,細膩噴霧質地。", description: "這款溫和的有機化妝水選用純正大馬士革玫瑰花水與保濕甘油精心調配。以細膩噴霧形式呈現,平衡並舒緩肌膚,為後續保養品的吸收做好準備。" },
      ja: { title: "ローズウォーター バランシング トナー", shortDescription: "グリセリン配合、細かいミストスプレーのオーガニックローズウォータートナー。", description: "純粋なダマスクローズウォーターと保湿力のあるグリセリンで作られた、優しいオーガニックトナー。細かいミストで肌に馴染ませることで、肌を整えてリフレッシュし、後に使用する製品の浸透を高めます。" },
      ko: { title: "로즈워터 밸런싱 토너", shortDescription: "글리세린을 담은 유기농 장미수 토너, 미세한 미스트 스프레이.", description: "순수한 다마스크 장미수와 보습력 있는 글리세린으로 만든 순한 유기농 토너입니다. 미세한 미스트로 분사되어 피부 밸런스를 맞추고 상쾌하게 정돈하며, 이후 제품의 흡수를 도와줍니다." },
